import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: parse tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  req.tenantId = host.split('.')[0];
  next();
});

// User lookup endpoint - supports flexible search
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { field, value, include_inactive } = req.query;

    // Validate field against allowed columns
    const ALLOWED_FIELDS = ['username', 'email', 'display_name', 'department', 'employee_id'];
    if (!ALLOWED_FIELDS.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Build query with tenant isolation
    // NOTE: field is validated above against allowlist, safe to interpolate
    let query = `SELECT id, username, email, display_name, department, created_at 
                 FROM tenant_users 
                 WHERE tenant_id = $1 AND ${field} `;

    const params = [req.tenantId];

    // Support LIKE searches with wildcard
    if (value && value.includes('*')) {
      query += `LIKE $2`;
      params.push(value.replace(/\*/g, '%'));
    } else {
      query += `= $2`;
      params.push(value);
    }

    if (include_inactive !== 'true') {
      query += ` AND status = 'active'`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);

    // Log search for audit
    await pool.query(
      `INSERT INTO search_audit_log (tenant_id, searched_field, searched_value, result_count, ts) VALUES ($1, $2, $3, $4, NOW())`,
      [req.tenantId, field, value, result.rows.length]
    );

    return res.json({ users: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/users/export', async (req, res) => {
  try {
    const { format, filters } = req.body;
    const sortCol = req.body.sort || 'created_at';
    const sortDir = req.body.direction || 'DESC';

    // Construct export query
    let query = `SELECT id, username, email, display_name, department, employee_id, 
                        status, created_at, last_login 
                 FROM tenant_users WHERE tenant_id = $1`;
    const params = [req.tenantId];

    if (filters && filters.department) {
      params.push(filters.department);
      query += ` AND department = $${params.length}`;
    }

    if (filters && filters.status) {
      params.push(filters.status);
      query += ` AND status = $${params.length}`;
    }

    // Sort - validated against allowlist
    const SORT_COLS = ['created_at', 'username', 'email', 'last_login', 'department'];
    const safeSortCol = SORT_COLS.includes(sortCol) ? sortCol : 'created_at';
    const safeSortDir = sortDir.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${safeSortCol} ${safeSortDir}`;

    // VULNERABILITY: unvalidated LIMIT/OFFSET from user input
    // allows SQL injection via crafted numeric-looking payload
    const limit = req.body.limit || '1000';
    const offset = req.body.offset || '0';
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);

    const exportId = crypto.randomUUID();
    res.json({ export_id: exportId, records: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Export error:', err.message);
    return res.status(500).json({ error: 'Export failed' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`User service running on port ${process.env.PORT || 3000}`);
});
